<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Relations\BelongsTo; class FreeServer extends Model { public const RESOURCE_NAME = 'free_server'; protected bool $immutableDates = true; protected $table = 'dezerx_free_servers'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'user_id' => 'int', 'renewals' => 'int', 'renew_at' => 'datetime', 'last_renewed_at' => 'datetime', 'suspended_at' => 'datetime', ]; public static array $validationRules = [ 'server_id' => 'required|int|exists:servers,id', 'user_id' => 'required|int|exists:users,id', ]; public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function owner(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } public function isOverdue(): bool { return $this->renew_at !== null && $this->renew_at->isPast(); } public function wasSuspendedForNonRenewal(): bool { return $this->suspended_at !== null; } } 